#!/usr/bin/env bash
# Adds one kubeconfig context per question. Generated by Quick Create.
set -euo pipefail

for cfg in /home/ubuntu/.kube/config /root/.kube/config; do
  [[ -f "$cfg" ]] || continue
  for ctx in k8s-web k8s-alpha; do
    kubectl --kubeconfig "$cfg" config set-context "$ctx" --cluster=kubernetes --user=kubernetes-admin --namespace=default >/dev/null
  done
  kubectl --kubeconfig "$cfg" config get-contexts -o name | grep -qx "k8s-alpha"
done
chown -R ubuntu:ubuntu /home/ubuntu/.kube
